import ast
import base64
import hashlib
import io
import os
import shutil
import sys
import zipfile
from pathlib import Path

MARKER = 'NEXTORY_FORMAT_CONTROL_V1'

def patch(src):
    if 'NEXTORY_SINGLE_PRESENTATION_V2' not in src or 'NEXTORY_NAMED_HLS_URL' not in src:
        sys.exit('ERROR: Verwachte Single HLS v2 + named URL broncode ontbreekt.')
    edits = {
        'async def public_track(session_id: str, track_index: int, req: Request):\n':
            '    if format_control.is_session(session_id):\n        return format_control.track(session_id, track_index, req)\n',
        'async def sync_session(session_id: str, req: Request, _: bool = Depends(authenticated)):\n':
            '    if format_control.is_session(session_id):\n        return format_control.sync(session_id)\n',
        'async def close_session(session_id: str, req: Request, _: bool = Depends(authenticated)):\n':
            '    if format_control.is_session(session_id):\n        return format_control.sync(session_id, close=True)\n',
    }
    for anchor, body in edits.items():
        if src.count(anchor) != 1:
            sys.exit('ERROR: Onverwachte broncode bij '+anchor.strip())
        src = src.replace(anchor, anchor+body, 1)
    src += '\n\n# NEXTORY_FORMAT_CONTROL_V1\nimport sys as _format_control_sys\nfrom . import format_control\nformat_control.install(_format_control_sys.modules[__name__])\n'
    ast.parse(src)
    return src


test, original = (Path(p).resolve(strict=True) for p in sys.argv[1:3])
mode = sys.argv[3]
appdir = test/'app'
main = appdir/'main.py'
helper = appdir/'format_control.py'
media = appdir/'format_control_media'
backup = test/'.nextory-format-control-baseline.py'
if any(p.is_symlink() for p in (appdir, main, helper, media, backup)) or main.samefile(original/'app/main.py'):
    sys.exit('ERROR: Onveilige broncodepaden.')
if (original/'app/format_control.py').exists() or (original/'app/format_control_media').exists():
    sys.exit('ERROR: Onverwachte controlebestanden in origineel.')
with zipfile.ZipFile(io.BytesIO(base64.b64decode(ARCHIVE))) as archive:
    payload = {name: archive.read(name) for name in archive.namelist()}
assert set(payload) == set(EXPECTED)
for name, data in payload.items():
    assert hashlib.sha256(data).hexdigest() == EXPECTED[name]
    if name.startswith('/') or '..' in Path(name).parts:
        sys.exit('ERROR: Ongeldig mediapad.')
module_source = payload.pop('format_control.py')
ast.parse(module_source)
current = main.read_text(encoding='utf-8')
baseline = backup.read_text(encoding='utf-8') if backup.exists() else current
if MARKER in baseline:
    sys.exit('ERROR: Baseline niet schoon.')
modified = patch(baseline)
if current not in (baseline, modified):
    sys.exit('ERROR: Broncode gewijzigd; niets overschrijven.')

def assets_match():
    if not helper.is_file() or helper.is_symlink() or helper.read_bytes()!=module_source or not media.is_dir() or media.is_symlink():
        return False
    existing = {}
    for p in media.rglob('*'):
        if p.is_symlink():
            return False
        if p.is_file(): existing['format_control_media/'+p.relative_to(media).as_posix()] = p.read_bytes()
    return existing == payload

def replace_main(text):
    tmp = main.with_name('.format-control-main-tmp')
    if tmp.exists() or tmp.is_symlink():
        sys.exit('ERROR: Tijdelijk bronbestand bestaat al.')
    try:
        tmp.write_text(text, encoding='utf-8')
        os.chmod(tmp, main.stat().st_mode & 0o777)
        os.replace(tmp, main)
    finally:
        tmp.unlink(missing_ok=True)

if mode == 'rollback':
    if not backup.exists() or current != modified or not assets_match():
        sys.exit('ERROR: Geen exacte geinstalleerde versie; rollback afgebroken.')
    replace_main(baseline)
    helper.unlink()
    shutil.rmtree(media)
    print('FORMAT_CONTROL=REMOVED')
    print('BASELINE_RESTORED=YES')
elif current == modified:
    if not assets_match():
        sys.exit('ERROR: Geinstalleerde fixtures wijken af.')
    print('FORMAT_CONTROL=ALREADY_ENABLED')
else:
    if helper.exists() or media.exists():
        sys.exit('ERROR: Onbekende bestaande controlebestanden.')
    if not backup.exists(): shutil.copy2(main, backup)
    try:
        helper.write_bytes(module_source)
        helper.chmod(0o644)
        media.mkdir(mode=0o755)
        for name, data in payload.items():
            p = appdir/name
            p.parent.mkdir(mode=0o755, parents=True, exist_ok=True)
            p.write_bytes(data)
            p.chmod(0o644)
        if not assets_match(): raise RuntimeError('Fixture integrity mismatch')
        replace_main(modified)
    except Exception:
        helper.unlink(missing_ok=True)
        if media.exists(): shutil.rmtree(media)
        raise
    print('FORMAT_CONTROL=ENABLED')
    print('PROBE_LIBRARY=Playback format test')
    print('FIXTURES=A_DIRECT_M4A,B_HLS_TS,C_HLS_FMP4')
    print('PROBE_MEDIA=GENERATED_LOCAL_TONE_ONLY')
print('PREVIOUS_NEXTORY_ROUTE=PRESERVED')
print('PYTHON_SYNTAX=PASS')

PYCODE
